// Extract message data from Facebook webhook.
const entry = $input.first().json.body?.entry?.[0];
const messaging = entry?.messaging?.[0];
const userId = messaging?.sender?.id;
const pageId = messaging?.recipient?.id;
const messageText = messaging?.message?.text;
const timestamp = messaging?.timestamp || Date.now();
const messageId = messaging?.message?.mid;
const sessionKey = `${userId}:${pageId}`;
const staticData = $getWorkflowStaticData('global');

// Pause AI while a human handoff is active.
if (!staticData.handoffSessions) staticData.handoffSessions = {};
const handoff = staticData.handoffSessions[sessionKey];
if (handoff) {
  if (Number(handoff.until) > Date.now()) {
    return { json: { userId, pageId, messageText, timestamp, messageId, skip: true, handoff_active: true } };
  }
  delete staticData.handoffSessions[sessionKey];
}

// Avoid re-processing duplicate Meta webhook deliveries for a short retention window.
if (!staticData.recentMessageIds) staticData.recentMessageIds = {};
const cutoff = Date.now() - 10 * 60 * 1000;
for (const [id, seenAt] of Object.entries(staticData.recentMessageIds)) {
  if (Number(seenAt) < cutoff) delete staticData.recentMessageIds[id];
}
if (messageId && staticData.recentMessageIds[messageId]) {
  return { json: { userId, pageId, messageText, timestamp, messageId, skip: true, duplicate: true } };
}
if (messageId) staticData.recentMessageIds[messageId] = Date.now();

if (!staticData.messageBatches) staticData.messageBatches = {};
if (!staticData.messageBatches[sessionKey]) {
  staticData.messageBatches[sessionKey] = {
    messages: [],
    firstMessageTime: timestamp,
    pageId
  };
}

staticData.messageBatches[sessionKey].messages.push({
  text: messageText,
  timestamp,
  messageId
});

return {
  json: {
    userId,
    pageId,
    messageText,
    timestamp,
    messageId,
    sessionKey,
    batchCount: staticData.messageBatches[sessionKey].messages.length,
    skip: false
  }
};

// Retrieve the complete message batch and attach the cached customer profile.
const store = $('Store Message for Batching').first().json;
const userId = store.userId;
const pageId = store.pageId;
const sessionKey = `${userId}:${pageId}`;
const staticData = $getWorkflowStaticData('global');

if (!staticData.handoffSessions) staticData.handoffSessions = {};
const handoff = staticData.handoffSessions[sessionKey];
if (handoff) {
  if (Number(handoff.until) > Date.now()) {
    return { json: { userId, pageId, sessionKey, skip: true, handoff_active: true } };
  }
  delete staticData.handoffSessions[sessionKey];
}

if (!staticData.messageBatches) staticData.messageBatches = {};
const userBatch = staticData.messageBatches[sessionKey];
if (!userBatch || userBatch.messages.length === 0) {
  return { json: { userId, pageId, sessionKey, skip: true } };
}

const combinedMessage = userBatch.messages
  .sort((a, b) => a.timestamp - b.timestamp)
  .map(m => m.text)
  .filter(Boolean)
  .join(' ');

delete staticData.messageBatches[sessionKey];

if (!staticData.customerProfiles) staticData.customerProfiles = {};
const customerProfile = staticData.customerProfiles[sessionKey] || {};

return {
  json: {
    userId,
    pageId,
    sessionKey,
    combinedMessage,
    messageCount: userBatch.messages.length,
    customerProfile,
    customer_profile_context: JSON.stringify(customerProfile),
    skip: false
  }
};

// Format the parsed AI response for Facebook Messenger.
const parsed = $('Parse AI Decision & Lead Data').first().json;
const userId = parsed.userId;
const pageId = parsed.pageId;

let formattedResponse = String(parsed.response || '').trim();
if (parsed.needs_human && !formattedResponse) {
  formattedResponse = 'Thanks for your message. A human support representative will take over from here.';
}
if (!formattedResponse) {
  formattedResponse = 'Thanks for your message. How can I help you today?';
}

// Messenger has a practical per-message character limit; keep a safe margin.
if (formattedResponse.length > 1900) {
  formattedResponse = formattedResponse.substring(0, 1897) + '...';
}

formattedResponse = formattedResponse
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/\*(.+?)\*/g, '$1')
  .replace(/```[\s\S]*?```/g, (match) => match.replace(/```\w*\n?/g, ''))
  .replace(/`(.+?)`/g, '$1');

return {
  json: {
    userId,
    pageId,
    response: formattedResponse,
    intent: parsed.intent,
    route: parsed.route,
    needs_human: parsed.needs_human
  }
};

// Parse AI JSON, normalize intent/lead data, persist a fast customer profile cache,
// and activate/deactivate a temporary human-handoff pause.
const raw = $input.first().json.output ?? $input.first().json.text ?? '';
let parsed;
try {
  const cleaned = String(raw)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  const candidate = start >= 0 && end > start ? cleaned.slice(start, end + 1) : cleaned;
  parsed = JSON.parse(candidate);
} catch (error) {
  parsed = {
    response: 'I’m sorry, but I need a moment to get a support specialist to help with that.',
    intent: 'other',
    route: 'human',
    needs_human: true,
    handoff_reason: 'AI output was invalid JSON; safe fallback applied.',
    lead: {},
    lead_score: 0,
    lead_status: 'human_handoff',
    knowledge_used: [],
    confidence: 0
  };
}

const base = $('Retrieve Batched Messages').first().json;
const userId = String(base.userId || '');
const pageId = String(base.pageId || '');
const sessionKey = `${userId}:${pageId}`;
const staticData = $getWorkflowStaticData('global');
if (!staticData.customerProfiles) staticData.customerProfiles = {};
if (!staticData.handoffSessions) staticData.handoffSessions = {};

const previousProfile = staticData.customerProfiles[sessionKey] || base.customerProfile || {};
const lead = parsed.lead && typeof parsed.lead === 'object' ? parsed.lead : {};
const rawIntent = String(parsed.intent || 'other').trim().toLowerCase();
const knownIntents = new Set(['sales','product_inquiry','pricing','order','booking','support','complaint','refund','faq','human_request','spam','other']);
const intent = knownIntents.has(rawIntent) ? rawIntent : 'other';

const explicitHuman = Boolean(parsed.needs_human) || String(parsed.route || '').toLowerCase() === 'human' || intent === 'human_request' || intent === 'complaint' || intent === 'refund';
const salesIntents = new Set(['sales','product_inquiry','pricing','booking']);
const route = explicitHuman ? 'human' : (salesIntents.has(intent) ? 'sales' : 'support');

const scoreInput = Number(parsed.lead_score ?? lead.lead_score ?? 0);
const newScore = Math.max(0, Math.min(100, Number.isFinite(scoreInput) ? scoreInput : 0));
const configRows = $('Load Business Knowledge Base').all().map(i => i.json || {}).filter(r => r.record_type === 'config');
const config = {};
for (const row of configRows) {
  const key = String(row.category || row.record_key || '').trim();
  if (key) config[key] = String(row.content ?? '').trim();
}
const qualifiedThreshold = Math.max(0, Math.min(100, Number(config.qualified_lead_score || 70)));
const handoffMinutes = Math.max(5, Math.min(1440, Number(config.handoff_pause_minutes || 30)));

const nonEmpty = (v, fallback = '') => {
  const value = String(v ?? '').trim();
  return value || String(fallback ?? '').trim();
};
const mergedLead = {
  name: nonEmpty(lead.name, previousProfile.name),
  email: nonEmpty(lead.email, previousProfile.email),
  phone: nonEmpty(lead.phone, previousProfile.phone),
  interest: nonEmpty(lead.interest, previousProfile.interest),
  budget: nonEmpty(lead.budget, previousProfile.budget),
  timeline: nonEmpty(lead.timeline, previousProfile.timeline),
  lead_score: Math.max(newScore, Number(previousProfile.lead_score) || 0)
};

let leadStatus = String(parsed.lead_status || '').trim().toLowerCase();
if (explicitHuman) leadStatus = 'human_handoff';
else if (mergedLead.lead_score >= qualifiedThreshold) leadStatus = 'qualified';
else if (route === 'support') leadStatus = 'support';
else leadStatus = leadStatus === 'qualified' ? 'qualified' : 'new';

const mergedProfile = {
  ...mergedLead,
  intent,
  route,
  lead_status: leadStatus,
  last_message: String(base.combinedMessage || ''),
  last_response: String(parsed.response || ''),
  needs_human: explicitHuman,
  updated_at: new Date().toISOString()
};
staticData.customerProfiles[sessionKey] = mergedProfile;

if (explicitHuman) {
  staticData.handoffSessions[sessionKey] = {
    until: Date.now() + handoffMinutes * 60 * 1000,
    reason: String(parsed.handoff_reason || 'Human assistance requested or required.'),
    createdAt: Date.now()
  };
} else {
  delete staticData.handoffSessions[sessionKey];
}

return {
  json: {
    ...base,
    business_config: {
      qualified_lead_score: qualifiedThreshold,
      handoff_pause_minutes: handoffMinutes,
      human_handoff_webhook_url: String(config.human_handoff_webhook_url || '').trim(),
      business_name: String(config.business_name || '').trim()
    },
    response: String(parsed.response || '').trim(),
    intent,
    route,
    needs_human: explicitHuman,
    handoff_reason: String(parsed.handoff_reason || (explicitHuman ? 'Human assistance requested or required.' : '')).trim(),
    lead: mergedLead,
    lead_status: leadStatus,
    knowledge_used: Array.isArray(parsed.knowledge_used) ? parsed.knowledge_used : [],
    confidence: Math.max(0, Math.min(1, Number(parsed.confidence) || 0))
  }
};
